const raw = $input.item.json.message?.text || '';
const text = raw.toLowerCase().trim();
const chatId = $input.item.json.message.chat.id;

const staticData = $getWorkflowStaticData('global');
let statusMsg = '⏳ One moment...';
let isWPIntent = false;
let isReset = false;
let isCategory = false;
let newsQuery = '';

const catMap = {
  business:      { label: 'Business',      query: 'business OR finance news' },
  finance:       { label: 'Business',      query: 'business OR finance news' },
  entertainment: { label: 'Entertainment', query: 'entertainment OR arts OR culture news' },
  arts:          { label: 'Entertainment', query: 'entertainment OR arts OR culture news' },
  environment:   { label: 'Environment',   query: 'environment OR nature OR climate news' },
  nature:        { label: 'Environment',   query: 'environment OR nature OR climate news' },
  science:       { label: 'Science',       query: 'science OR technology OR AI news' },
  technology:    { label: 'Science',       query: 'science OR technology OR AI news' },
  politics:      { label: 'Politics',      query: 'UK politics OR global news OR parliament OR international affairs' },
  global:        { label: 'Politics',      query: 'UK politics OR global news OR parliament OR international affairs' }
};

// Reset: /start, /reset, and "new article" style phrases
if (text === '/start' || text === '/reset' ||
    /\b(new article|new post|start new|fresh start|another article|write another|begin again|start over|start again|lets start|create (a |an )?new|draft (a |an )?(new )?article|i want to (create|draft|write))\b/.test(text)) {
  isReset = true;
  statusMsg = '🔄 Resetting your PromoMag session...';
}
// WordPress intent — detect draft vs publish
else if (/\b(post|publish|wordpress|wp|send to wp|commit|draft it|push|upload)\b/.test(text)) {
  isWPIntent = true;
  // "publish" or "go live" or "make it live" = publish status
  // "draft" or "save as draft" or just "post to wordpress" = draft
  const isPublish = /\b(publish|go live|make it live|publish it|post live|live)\b/.test(text);
  statusMsg = isPublish
    ? '🚀 *Publishing to PromoMag...*\n\n_Going live on PromoMag.co.uk_'
    : '📤 *Posting to WordPress as draft...*\n\n_Connecting to PromoMag.co.uk_';
}
// Topic number selection — catch "3", "3 please", "3 looks good", "go with 3", "option 3" etc
// Must detect a number 1-5 AND NOT be a question about "other options"
else if (/\b[1-5]\b/.test(text) && !/\b(other|more|another|different|alt|option[s]?|what|any)\b/.test(text) && text.length < 60) {
  statusMsg = '📋 Got it — preparing your article outline...';
}
// Proceed/confirm — write article
else if (/\b(yes|yep|proceed|write|go ahead|confirm|draft|do it|sounds good|perfect|great|sure|ok|okay|procees|proce)\b/.test(text) && !/wordpress|publish|post it|send to wp/.test(text)) {
  statusMsg = '✍️ *Writing your full article now...*\n\n_Drafting all sections in one pass — around 30–60 seconds._';
}
// Social media
else if (/\b(social|twitter|linkedin|facebook|instagram|hashtag|share|tiktok|reels)\b/.test(text)) {
  statusMsg = '📱 *Building your social media pack...*';
}
// Article topic intent — "I want an article about X", "write about Y", "create a piece on Z"
// Routes free-text topic requests through the research pipeline
else if (
  !staticData['categoryChosen_' + chatId] &&
  /\b(article|piece|write|draft|create|post)\b/.test(text) &&
  /\b(about|on|regarding|covering)\b/.test(text) &&
  text.length > 15
) {
  isCategory = true;
  // Extract the topic from the message
  newsQuery = text
    .replace(/^(i want|write me|create|draft|can you write|please write|an article|a piece|a post)(\s+(about|on|regarding|covering))?/gi, '')
    .replace(/\b(i want|write me|create|draft|an article|a piece|about|regarding|on the topic of|please|can you)\b/gi, '')
    .replace(/[^a-zA-Z0-9 ]/g, ' ')
    .trim()
    .slice(0, 80);
  if (!newsQuery || newsQuery.length < 3) newsQuery = text.slice(0, 80);
  staticData['categoryChosen_' + chatId] = true;
  statusMsg = '🔍 *Researching live news on that topic...*\n\n_This may take 20–30 seconds._';
}

// Category selection
// Guard 1: Only fire if no category chosen yet this session
// Guard 2: Max 30 chars — longest valid input is 'politics and global news' (24 chars)
// Guard 3: No question/filter words
else if (
  !staticData['categoryChosen_' + chatId] &&
  text.length <= 30 &&
  /\b(business|finance|entertainment|arts|environment|nature|science|technology|politics)\b/.test(text) &&
  !/\b(other|more|another|different|what|any|option[s]?)\b/.test(text)
) {
  const keyword = text.match(/business|finance|entertainment|arts|environment|nature|science|technology|politics/)[0];
  const info = catMap[keyword];
  isCategory = true;
  newsQuery = info.query;
  staticData['categoryChosen_' + chatId] = true;
  statusMsg = '🔍 Researching trending *' + info.label + '* topics from Reuters, Bloomberg, BBC and more...\n\n_This may take 20–30 seconds._';
}

// Determine publish vs draft for the return payload
const isPublish = isWPIntent && /\b(publish|go live|make it live|publish it|post live|live)\b/.test(text);
return [{ json: { chatId, statusMsg, isWPIntent, isReset, isCategory, newsQuery, isPublish, originalText: raw } }];

const CHUNK_SIZE = 3800;
const output = $input.item.json.output || '';
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const items = [];

const extractBlock = (tag, text) => {
  const open = '[BLOCK:' + tag + ']';
  const close = '[/BLOCK]';
  const start = text.indexOf(open);
  if (start === -1) return null;
  const contentStart = start + open.length;
  const end = text.indexOf(close, contentStart);
  return end === -1 ? text.slice(contentStart).trim() : text.slice(contentStart, end).trim();
};

const parseField = (block, field) => {
  if (!block) return '';
  const lines = block.split('\n');
  for (const line of lines) {
    const prefix = field + ': ';
    if (line.startsWith(prefix)) return line.slice(prefix.length).trim();
  }
  return '';
};

const chunkText = (text) => {
  const chunks = [];
  let remaining = text;
  while (remaining.length > 0) {
    let chunk = remaining.slice(0, CHUNK_SIZE);
    if (remaining.length > CHUNK_SIZE) {
      const lastNewline = chunk.lastIndexOf('\n');
      if (lastNewline > CHUNK_SIZE * 0.5) chunk = chunk.slice(0, lastNewline);
    }
    chunks.push(chunk.trim());
    remaining = remaining.slice(chunk.length).trim();
  }
  return chunks;
};

const metadataBlock = extractBlock('METADATA', output);
const articleBlock = extractBlock('ARTICLE', output);
const seoBlock = extractBlock('SEO', output);
const isCompleteArticle = !!(metadataBlock && articleBlock && seoBlock);
const hasBlocks = !!(metadataBlock || articleBlock || seoBlock);

const detectCategory = (meta) => {
  const author = parseField(meta, 'Author').toLowerCase();
  if (author.indexOf('business') !== -1 || author.indexOf('finance') !== -1) return 'business-finance';
  if (author.indexOf('entertainment') !== -1 || author.indexOf('arts') !== -1) return 'entertainment-arts';
  if (author.indexOf('environment') !== -1 || author.indexOf('nature') !== -1) return 'environment-nature';
  if (author.indexOf('science') !== -1 || author.indexOf('technology') !== -1) return 'science-technology';
  if (author.indexOf('politics') !== -1 || author.indexOf('global') !== -1 || author.indexOf('news') !== -1) return 'politics-global';
  return 'uncategorized';
};

if (isCompleteArticle) {
  const staticData = $getWorkflowStaticData('global');
  staticData['currentChatId'] = chatId; // reliable chatId for post-Merge nodes
  staticData['article_' + chatId] = {
    title: parseField(metadataBlock, 'Title'),
    slug: parseField(metadataBlock, 'Slug'),
    excerpt: parseField(metadataBlock, 'Meta'),
    tags: parseField(metadataBlock, 'Tags'),
    imageDescription: parseField(metadataBlock, 'Image'),
    content: articleBlock,
    category: detectCategory(metadataBlock),
    wpMediaId: 0,
    wpMediaUrl: null
  };
}

if (isCompleteArticle) {
  items.push({ json: { chatId: chatId, text: '📰 *Article Brief*\n\n' + metadataBlock, generateImage: false } });

  const clean = articleBlock
    .split('\n')
    .filter(function(l) { return !l.trim().match(/^#{1,6}\s/); })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const chunks = chunkText(clean);
  for (let i = 0; i < chunks.length; i++) {
    const label = chunks.length > 1
      ? '✍️ *Article Body (' + (i + 1) + '/' + chunks.length + ')*\n\n' + chunks[i]
      : '✍️ *Article Body*\n\n' + chunks[i];
    items.push({ json: { chatId: chatId, text: label, generateImage: false } });
  }

  // SEO block — triggers image generation ONLY on complete article
  items.push({ json: { chatId: chatId, text: '📣 *Next Step*\n\n' + seoBlock, generateImage: true } });

} else if (hasBlocks) {
  // Partial blocks — strip markers and output as plain text, no image trigger
  const partialText = output
    .replace(/\[BLOCK:[^\]]+\]/g, '')
    .replace(/\[\/BLOCK\]/g, '')
    .trim();
  const chunks = chunkText(partialText || output);
  for (let i = 0; i < chunks.length; i++) {
    items.push({ json: { chatId: chatId, text: chunks[i], generateImage: false } });
  }
} else {
  // Plain conversational response (category prompt, topic list, table of contents, social pack)
  // No image trigger — never fire on anything except a complete article
  const chunks = chunkText(output || 'No response generated.');
  for (let i = 0; i < chunks.length; i++) {
    items.push({ json: { chatId: chatId, text: chunks[i], generateImage: false } });
  }
}

return items.length > 0
  ? items
  : [{ json: { chatId: chatId, text: '⚠️ No content returned. Please try again.', generateImage: false } }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const article = staticData['article_' + chatId];

// Read publish intent from Detect Stage
const isPublish = $('Detect Stage').item.json.isPublish || false;

if (!article) {
  return [{ json: {
    chatId: chatId, error: true,
    errorMsg: '⚠️ *No article found*\n\nDraft an article first, then reply *post to WordPress* or *publish to WordPress*.'
  }}];
}

return [{ json: {
  chatId: chatId, error: false,
  title: article.title || 'Untitled Article',
  content: article.content || '',
  slug: article.slug || '',
  excerpt: article.excerpt || '',
  tags: article.tags || '',
  category: article.category || 'uncategorized',
  wpMediaId: article.wpMediaId || 0,
  isPublish: isPublish
}}];

const raw = $json.content || '';

const html = raw
  .split('\n')
  .filter(function(line) { return !line.trim().match(/^#{1,6}\s/); })
  .join('\n')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>')
  .replace(/^>\s?(.+)/gm, '<blockquote>$1</blockquote>')
  .split(/\n\n+/)
  .map(function(para) {
    const t = para.trim();
    if (!t) return '';
    if (t.startsWith('<blockquote>')) return t;
    return '<p>' + t.replace(/\n/g, '<br>') + '</p>';
  })
  .filter(Boolean)
  .join('\n\n');

return [{ json: {
  chatId: $json.chatId,
  title: $json.title,
  content: html,
  slug: $json.slug,
  excerpt: $json.excerpt,
  tags: $json.tags,
  category: $json.category || 'uncategorized',
  wpMediaId: $json.wpMediaId || 0,
  isPublish: $json.isPublish || false
}}];

// PromoMag.co.uk verified category IDs
// Source: https://promomag.co.uk/wp-json/wp/v2/categories
const categoryMap = {
  'business-finance':   2,
  'entertainment-arts': 105,
  'environment-nature': 162,
  'science-technology': 296,
  'politics-global':    5325
};

const slug = $json.category || 'uncategorized';
const categoryId = categoryMap[slug] || 1;

return [{ json: {
  chatId: $json.chatId,
  title: $json.title,
  content: $json.content,
  slug: $json.slug,
  excerpt: $json.excerpt,
  tags: $json.tags,
  wpMediaId: $json.wpMediaId || 0,
  categoryId: categoryId,
  isPublish: $json.isPublish || false
}}];

