const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'] || $json.chatId;
const wpResponse = $input.item.json.body || $input.item.json;
const postId = wpResponse.id;
const isPublished = wpResponse.status === 'publish';
const postUrl = wpResponse.link || ('https://promomag.co.uk/?p=' + postId);

return [{ json: {
  chatId: chatId,
  text: isPublished
    ? '🚀 *Article published on PromoMag!*\n\n📄 Status: Live\n\n🔗 [View Article](' + postUrl + ')\n🔗 [Edit in WP Admin](https://promomag.co.uk/wp-admin/post.php?post=' + postId + '&action=edit)'
    : '✅ *Article saved as draft on PromoMag!*\n\n📄 Status: Draft\n\n🔗 [Open in WP Admin](https://promomag.co.uk/wp-admin/post.php?post=' + postId + '&action=edit)\n\n_Review and publish when ready._'
}}];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'] || $json.chatId;
const err = $json.error ? $json.error.message : JSON.stringify($json).slice(0, 200);
return [{ json: {
  chatId: chatId,
  text: '⚠️ *WordPress Post Failed*\n\nCheck your WP credentials in n8n.\n\n_Error: ' + String(err).slice(0, 200) + '_'
}}];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const errorMsg = $input.item.json.error ? $input.item.json.error.message : 'Unknown error';
return [{ json: { chatId: chatId, text: '⚠️ *PromoMag Error*

Something went wrong. Send /reset to start fresh.

_' + String(errorMsg).slice(0, 200) + '_' } }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');

// Clear stored article
if (staticData['article_' + chatId]) {
  delete staticData['article_' + chatId];
}

// Clear category chosen flag so detection works fresh next session
delete staticData['categoryChosen_' + chatId];

// Increment session counter for memory isolation
const counterKey = 'sessionCounter_' + chatId;
staticData[counterKey] = (staticData[counterKey] || 0) + 1;

return [{ json: {
  chatId: chatId,
  text: '\u2705 *Session reset.*\n\nAll previous article data cleared. Choose a category to begin a new article.\n\nBusiness & Finance | Entertainment & Arts | Environment & Nature | Science & Technology | Politics & Global News'
}}];

const staticData = $getWorkflowStaticData('global');

let chatId;
try {
  chatId = $('Telegram Trigger').item.json.message.chat.id;
} catch(e) {
  chatId = staticData['currentChatId'];
}

if (!chatId) throw new Error('Could not resolve chatId for image generation');

const article = staticData['article_' + chatId];
if (!article) throw new Error('No stored article found for chatId: ' + chatId);

const imageDescription = article.imageDescription || article.title || 'Professional editorial magazine photograph';

const imagePrompt = [
  'Professional editorial magazine header photograph for a web publication.',
  imageDescription,
  'Cinematic lighting, photojournalism aesthetic, widescreen 16:9 composition.',
  'No people, no faces, no portraits, no humans visible.',
  'Focus on objects, landscapes, technology, architecture, abstract concepts, or symbolic imagery.',
  'No text, no watermarks, no logos.'
].join(' ');

return [{ json: { chatId, imagePrompt } }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const article = staticData['article_' + chatId];
const title = (article && article.title) ? article.title : 'promomag-article';
const filename = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60) + '-featured.png';

// Pass binary data through so Upload to WP Media can find imageData
return [{
  json: { chatId: chatId, filename: filename },
  binary: $input.item.binary
}];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'];

if (!chatId) {
  return [{ json: { chatId: null, wpMediaId: null, wpMediaUrl: null } }];
}

const raw = $input.item.json;
const body = raw.body || raw;

const wpMediaId = body.id || null;
const wpMediaUrl = body.source_url
  || (body.guid && body.guid.rendered)
  || (body.guid && body.guid.raw)
  || null;

if (wpMediaId) {
  if (staticData['article_' + chatId]) {
    staticData['article_' + chatId].wpMediaId = wpMediaId;
    staticData['article_' + chatId].wpMediaUrl = wpMediaUrl;
  }
}

// Log for debugging
if (!wpMediaUrl) {
  console.log('Store WP Media ID: wpMediaUrl is null. Raw response:', JSON.stringify(raw).slice(0, 500));
}

return [{ json: {
  chatId,
  wpMediaId,
  wpMediaUrl,
  hasUrl: !!wpMediaUrl
} }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const raw = $input.item.json;

// Extract error in whatever format n8n provides
let err = 'Unknown error';
if (raw.error) {
  if (typeof raw.error === 'string') {
    err = raw.error;
  } else if (raw.error.message) {
    err = raw.error.message;
  } else if (raw.error.description) {
    err = raw.error.description;
  } else {
    err = JSON.stringify(raw.error).slice(0, 300);
  }
} else if (raw.message) {
  err = raw.message;
} else if (raw.statusCode) {
  err = 'HTTP ' + raw.statusCode + ': ' + JSON.stringify(raw).slice(0, 200);
}

return [{ json: {
  chatId: chatId,
  text: '⚠️ *Image generation failed*\n\nYou can still post to WordPress — reply *post to WordPress*. Add a featured image manually in WP Admin.\n\n_Error: ' + String(err).slice(0, 300) + '_'
}}];

// Parse all RSS feeds merged from multiple queries
// Input: merged RSS text from multiple Google News fetches
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const category = $('Detect Stage').item.json.newsQuery || '';

// Get current date
const now = new Date();
const currentDate = now.toLocaleDateString('en-GB', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// Collect all RSS data from input items (could be multiple feeds merged)
let allRssData = '';
const items = $input.all ? $input.all() : [$input.item];
for (const item of items) {
  allRssData += (item.json.data || item.json.content || '') + '\n';
}

// Parse all <item> elements across all feeds
const articles = [];
const seen = new Set();
const itemRegex = /<item>[\s\S]*?<\/item>/g;
let match;
while ((match = itemRegex.exec(allRssData)) !== null && articles.length < 15) {
  const rssItem = match[0];

  const titleMatch = rssItem.match(/<title><!\[CDATA\[(.*?)\]\]><\/title>/) || rssItem.match(/<title>(.*?)<\/title>/);
  const rawTitle = titleMatch ? (titleMatch[1] || '').trim() : '';
  if (!rawTitle || rawTitle.toLowerCase().includes('google news')) continue;

  // Deduplicate by headline
  if (seen.has(rawTitle)) continue;
  seen.add(rawTitle);

  const lastDash = rawTitle.lastIndexOf(' - ');
  const headline = lastDash > 0 ? rawTitle.slice(0, lastDash).trim() : rawTitle;
  const source = lastDash > 0 ? rawTitle.slice(lastDash + 3).trim() : '';

  const pubDateMatch = rssItem.match(/<pubDate>(.*?)<\/pubDate>/);
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : '';

  const descMatch = rssItem.match(/<description><!\[CDATA\[(.*?)\]\]><\/description>/) || rssItem.match(/<description>(.*?)<\/description>/);
  const rawDesc = descMatch ? descMatch[1] : '';
  const description = rawDesc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);

  articles.push({ headline, source, pubDate, description });
}

// Format as research brief for the Research Agent
const researchInput = articles.map(function(a, i) {
  let entry = (i + 1) + '. ' + a.headline;
  if (a.source) entry += ' [' + a.source + ']';
  if (a.pubDate) entry += ' (' + a.pubDate + ')';
  if (a.description) entry += '\n   ' + a.description;
  return entry;
}).join('\n\n');

// Save for later use in writing step
staticData['researchInput_' + chatId] = researchInput;
staticData['researchDate_' + chatId] = currentDate;
staticData['researchCategory_' + chatId] = category;

return [{ json: {
  chatId,
  currentDate,
  category,
  researchInput,
  articleCount: articles.length
}}];

const originalText = $('Telegram Trigger').item.json.message.text;
const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');

const now = new Date();
const currentDate = staticData['researchDate_' + chatId]
  || now.toLocaleDateString('en-GB', {weekday:'long',day:'numeric',month:'long',year:'numeric'});

let promptText = '[CURRENT DATE: ' + currentDate + ']\n\n' + originalText;

// Re-inject structured research brief so Writing Agent has sources when drafting
const researchBrief = staticData['researchBrief_' + chatId];
if (researchBrief) {
  promptText += '\n\n[RESEARCH BRIEF — Use these sourced facts to ground the article. '
    + 'Reference specific figures, names, and sources from this brief:]\n\n'
    + researchBrief;
}

return [{ json: { promptText } }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const staticData = $getWorkflowStaticData('global');
const counter = staticData['sessionCounter_' + chatId] || 0;
const sessionKey = chatId + '_' + counter;
const promptText = $input.item.json.promptText || $('Telegram Trigger').item.json.message.text;

return [{ json: { promptText, sessionKey, chatId } }];

const staticData = $getWorkflowStaticData('global');

// Primary: Telegram Trigger item. Fallback: currentChatId from static data
let chatId;
try {
  chatId = $('Telegram Trigger').item.json.message.chat.id;
} catch(e) {
  chatId = staticData['currentChatId'];
}

const article = staticData['article_' + chatId];
const title = (article && article.title) ? article.title : '';
const tags = (article && article.tags) ? article.tags : '';

const stopWords = new Set(['the','a','an','of','in','on','at','to','for','with','and','or','but',
  'is','are','was','were','be','been','being','has','have','had','do','does','did',
  'will','would','could','should','may','might','shall','its','it','this','that',
  'how','why','what','when','where','who','which','by','from','as','into','through']);

const combined = (title + ' ' + tags).toLowerCase()
  .replace(/[^a-z0-9 ]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length > 3 && !stopWords.has(w))
  .slice(0, 4)
  .join(' ');

const query = combined || title.split(' ').slice(0, 3).join(' ') || 'editorial news';

return [{ json: { chatId, query, imageDescription: article ? article.imageDescription : '' } }];

const chatId = $('Telegram Trigger').item.json.message.chat.id;
const response = $input.item.json;

let imageUrl = null;

if (response && response.hits && response.hits.length > 0) {
  const hit = response.hits.find(function(h) { return h.largeImageURL || h.webformatURL; });
  if (hit) {
    imageUrl = hit.largeImageURL || hit.webformatURL;
  }
}

return [{ json: { chatId: chatId, imageUrl: imageUrl, hasPixabay: !!imageUrl } }];

// Pixabay image found — pass URL through as JSON (no binary yet)
// Binary download happens after Merge to avoid binary data being stripped
return [{ json: { imageUrl: $json.imageUrl, source: 'pixabay' } }];

// DALL-E image generated — extract URL as JSON (no binary yet)
// Binary download happens after Merge
const url = $json.data && $json.data[0] ? $json.data[0].url : null;
if (!url) throw new Error('DALL-E returned no image URL');
return [{ json: { imageUrl: url, source: 'dalle' } }];

const tagNames = ($json.tags || '')
  .split(',')
  .map(function(t) { return t.trim(); })
  .filter(function(t) { return t.length > 1; })
  .slice(0, 8);

const chatId = $json.chatId;

// Save full post metadata to static data
// so it can be retrieved after the tag loop
const staticData = $getWorkflowStaticData('global');
staticData['pendingPost_' + chatId] = {
  chatId: chatId,
  title: $json.title,
  content: $json.content,
  slug: $json.slug,
  excerpt: $json.excerpt,
  wpMediaId: $json.wpMediaId || 0,
  categoryId: $json.categoryId || 1,
  isPublish: $json.isPublish || false,
  totalTags: tagNames.length,
  collectedTagIds: []
};

// Output one item per tag name so HTTP Request runs for each
if (tagNames.length === 0) {
  // No tags — pass through with empty tagIds
  return [{ json: {
    chatId: chatId,
    tagName: null,
    noTags: true,
    totalTags: 0
  }}];
}

return tagNames.map(function(name) {
  return { json: { chatId: chatId, tagName: name, noTags: false, totalTags: tagNames.length } };
});

const chatId = $json.chatId;
const staticData = $getWorkflowStaticData('global');
const pending = staticData['pendingPost_' + chatId];

if (!pending) {
  return [{ json: {
    chatId: chatId, title: $json.title || '', content: $json.content || '',
    slug: $json.slug || '', excerpt: $json.excerpt || '',
    wpMediaId: $json.wpMediaId || 0, categoryId: $json.categoryId || 1,
    tagIds: [], isPublish: $json.isPublish || false, tagNote: ''
  }}];
}

delete staticData['pendingPost_' + chatId];

return [{ json: {
  chatId: pending.chatId,
  title: pending.title,
  content: pending.content,
  slug: pending.slug,
  excerpt: pending.excerpt,
  wpMediaId: pending.wpMediaId || 0,
  categoryId: pending.categoryId || 1,
  tagIds: [],
  isPublish: pending.isPublish || false,
  tagNote: ''
}}];

// Single handler for BOTH new tag (success) and existing tag (error) responses
// Success response from WP: { id: 123, name: "tagname", ... }
// Error response from WP:   { code: "term_exists", data: { term_id: 123 }, ... }
const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'] || null;

const tagId = $json.id
  || ($json.data && $json.data.term_id)
  || null;

return [{ json: { chatId: chatId, tagId: tagId } }];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'];
const pending = staticData['pendingPost_' + chatId];

// Extract tag IDs from aggregated items
const tagItems = $json.tagItems || [];
const tagIds = tagItems
  .map(function(item) { return item.tagId; })
  .filter(Boolean);

if (!pending) {
  // Fallback — shouldn't happen but handle gracefully
  return [{ json: {
    chatId: chatId || '',
    title: '', content: '', slug: '', excerpt: '',
    wpMediaId: 0, categoryId: 1,
    tagIds: tagIds,
    isPublish: false,
    tagNote: 'Warning: pending post data not found'
  }}];
}

// Clean up
delete staticData['pendingPost_' + chatId];

return [{ json: {
  chatId: pending.chatId,
  title: pending.title,
  content: pending.content,
  slug: pending.slug,
  excerpt: pending.excerpt,
  wpMediaId: pending.wpMediaId || 0,
  categoryId: pending.categoryId || 1,
  tagIds: tagIds,
  isPublish: pending.isPublish || false,
  tagNote: tagIds.length > 0 ? '' : 'Tags could not be added'
}}];

